// --- Widget.h ---
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Destructor declaration is crucial!

    // Move operations are implicitly generated and correct
    Widget(Widget&&) noexcept;
    Widget& operator=(Widget&&) noexcept;

    // Copy operations must be implemented manually if needed
    Widget(const Widget& other);
    Widget& operator=(const Widget& other);

    void doSomething();

private:
    struct Impl; // Forward-declare the implementation struct
    std::unique_ptr<Impl> pImpl; // Use unique_ptr to manage it
};


// --- Widget.cpp ---
#include "Widget.h"
#include <string>
#include <vector>

// Full definition of the implementation struct
struct Widget::Impl {
    std::string name;
    std::vector<int> data;

    void doSomethingImpl() { /* ... */ }
};

// Destructor definition where Impl is a complete type
Widget::~Widget() = default;
Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;

// Constructor allocates the implementation object
Widget::Widget() 
    : pImpl(std::make_unique<Impl>()) {}

// Manual deep copy for copy constructor
Widget::Widget(const Widget& other)
    : pImpl(std::make_unique<Impl>(*other.pImpl)) {}

// Manual deep copy for copy assignment
Widget& Widget::operator=(const Widget& other) {
    if (this != &other) {
        *pImpl = *other.pImpl;
    }
    return *this;
}

void Widget::doSomething() {
    pImpl->doSomethingImpl();
}
